import { Box } from '@greysole/spooder-component-library';
import React, { ReactNode, useRef } from 'react';
import { CSSTransition } from 'react-transition-group';

interface FooterProps {
  showFooter: boolean;
  children: ReactNode;
}

export function Footer({ children, showFooter }: FooterProps) {
  const ref = useRef(null);
  return (
    <CSSTransition
      nodeRef={ref}
      classNames='slide'
      appear={showFooter}
      in={showFooter}
      timeout={300}
    >
      <Box ref={ref} className='footer' width='calc(100% - 4px)' height='var(--footer-height)' marginLeft='2px' marginRight='2px'>
        {children}
      </Box>
    </CSSTransition>
  );
}
